import {useEffect,useMemo,useState} from 'react';
import {Archive,Copy,FileText,Loader2,LockKeyhole,Plus,RefreshCw} from 'lucide-react';
import {archiveTemplate,createTemplate,duplicateTemplate,getTemplate,listTemplates,updateTemplate} from '../../lib/practiceOperationsApi';

const scopes=[['All',''],['System','SYSTEM'],['Practice','PRACTICE'],['My Templates','PRACTITIONER']];
const types=[['All',''],['Intake','INTAKE'],['Assessment','ASSESSMENT'],['Notes','SESSION_NOTE'],['Plans','PLAN'],['Messages','MESSAGE'],['Reports','PROGRESS_REPORT']];

export function ExternalTemplateLibrary(){
  const [items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[scope,setScope]=useState(''),[type,setType]=useState(''),[preview,setPreview]=useState(null);
  const load=async()=>{setState('loading');setError('');try{const result=await listTemplates();setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message||'Template library could not load.');setState('error')}};useEffect(()=>{void load()},[]);
  const visible=useMemo(()=>items.filter(item=>(!scope||item.scope===scope)&&(!type||item.template_type===type)),[items,scope,type]);
  const create=async()=>{const title=window.prompt('Custom template name');if(!title)return;try{await createTemplate({template_type:type||'SESSION_NOTE',scope:'PRACTITIONER',title,sections:[]});await load()}catch(reason){setError(reason.message);setState('error')}};
  const open=async id=>{try{setPreview(await getTemplate(id))}catch(reason){setError(reason.message);setState('error')}};
  const duplicate=async id=>{try{await duplicateTemplate(id);await load()}catch(reason){setError(reason.message);setState('error')}};
  const edit=async item=>{const detail=await getTemplate(item.id);const title=window.prompt('Template name',item.title);if(!title)return;await updateTemplate(item.id,{expected_version:item.current_version,title,description:item.description,sections:detail.sections.map(section=>({key:section.section_key,title:section.title,description:section.description,items:section.items.map(entry=>({key:entry.item_key,label:entry.label,item_type:entry.item_type,config:entry.config}))}))});await load()};
  const archive=async id=>{try{await archiveTemplate(id);setPreview(null);await load()}catch(reason){setError(reason.message);setState('error')}};
  if(state==='loading')return <div role="status" className="grid min-h-64 place-items-center rounded-3xl bg-white"><Loader2 className="animate-spin"/><span className="sr-only">Loading template library</span></div>;
  if(state==='error')return <div role="alert" className="rounded-2xl bg-red-50 p-5 text-red-800">{error}<button onClick={load} className="ml-3 min-h-11 px-3 font-bold"><RefreshCw className="inline"/> Retry</button></div>;
  return <section className="space-y-5"><header className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Governed resources</p><h2 className="mt-1 text-3xl font-bold">Template Library</h2><p className="mt-2 text-sm text-slate-500">Reusable, version-bound templates for your profession.</p></div><button onClick={create} className="min-h-11 rounded-xl bg-blue-700 px-4 font-semibold text-white"><Plus className="mr-1 inline" size={17}/>Create Custom</button></header><div className="space-y-3 rounded-2xl border bg-white p-3"><div className="flex gap-2 overflow-x-auto" aria-label="Template scope filters">{scopes.map(([label,value])=><button key={label} onClick={()=>setScope(value)} aria-pressed={scope===value} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-semibold ${scope===value?'bg-slate-950 text-white':'bg-slate-50 text-slate-600'}`}>{label}</button>)}</div><div className="flex gap-2 overflow-x-auto" aria-label="Template type filters">{types.map(([label,value])=><button key={label} onClick={()=>setType(value)} aria-pressed={type===value} className={`min-h-11 shrink-0 rounded-xl border px-3 text-xs font-semibold ${type===value?'border-blue-700 text-blue-700':'border-slate-200 text-slate-600'}`}>{label}</button>)}</div></div>{visible.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visible.map(item=><article key={item.id} className="rounded-2xl border bg-white p-5"><div className="flex items-start justify-between gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><FileText size={19}/></span>{item.scope==='SYSTEM'?<span className="flex items-center gap-1 text-xs font-bold text-slate-500"><LockKeyhole size={13}/>Locked System</span>:<span className="text-xs font-bold text-blue-700">{item.scope==='PRACTITIONER'?'My Template':'Practice'}</span>}</div><h3 className="mt-4 font-bold">{item.title}</h3><p className="mt-1 text-xs text-slate-500">{item.template_type.replaceAll('_',' ')} · Version {item.current_version}</p><div className="mt-5 flex flex-wrap gap-2"><button onClick={()=>open(item.id)} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Preview</button><button onClick={()=>duplicate(item.id)} className="min-h-11 rounded-xl border px-3 text-sm font-semibold"><Copy className="mr-1 inline" size={15}/>Duplicate</button>{item.scope!=='SYSTEM'&&<><button onClick={()=>edit(item)} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Edit Custom</button><button onClick={()=>archive(item.id)} aria-label={`Archive ${item.title}`} className="min-h-11 rounded-xl border px-3 text-sm text-rose-700"><Archive size={16}/></button></>}</div></article>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-9 text-center"><FileText className="mx-auto text-blue-700"/><h3 className="mt-3 font-semibold">No templates match these filters.</h3><p className="mt-1 text-sm text-slate-500">This is a confirmed empty library state.</p></div>}{preview&&<div role="dialog" aria-modal="true" aria-label="Template preview" className="fixed inset-0 z-50 flex justify-end bg-slate-950/40" onClick={()=>setPreview(null)}><section onClick={event=>event.stopPropagation()} className="h-full w-full max-w-xl overflow-y-auto bg-white p-6"><button onClick={()=>setPreview(null)} className="float-right min-h-11 rounded-xl border px-3">Close</button><p className="text-xs font-bold uppercase text-blue-700">Preview · Version {preview.version.version}</p><h2 className="mt-2 text-2xl font-bold">{preview.definition.title}</h2>{preview.locked&&<p className="mt-3 rounded-xl bg-slate-100 p-3 text-sm"><LockKeyhole className="mr-2 inline" size={16}/>System templates are immutable. Duplicate to customise.</p>}<div className="mt-6 space-y-4">{preview.sections.map(section=><article key={section.id} className="rounded-2xl border p-4"><h3 className="font-semibold">{section.title}</h3>{section.items.map(item=><p key={item.id} className="mt-2 text-sm text-slate-600">{item.label}</p>)}</article>)}</div></section></div>}</section>;
}
